grant execute on function public.run_rosetta_v3_extraction(integer,text,text,text,text,text,text,text,date,text,jsonb) to service_role

comment on function public.run_rosetta_v3_extraction(integer,text,text,text,text,text,text,text,date,text,jsonb) is 'Rosetta 2.5.2 canonical decomposition. Preserves the 2.5 parser/provenance contract, the 2.5.1 accountability action classifier, and corrects penalty actor boundaries before independent validation.'

